    function imInitialLang(fallback) {
      try {
        const q = new URLSearchParams(window.location.search).get('lang');
        if (q === 'en' || q === 'ko') return q;
        const s = localStorage.getItem('im_lang');
        if (s === 'en' || s === 'ko') return s;
      } catch (e) { }
      return fallback;
    }

    let lang = imInitialLang('ko');
